package api

import (
	_ "embed"
	"net/http"

	"github.com/gin-gonic/gin"
)

// swaggerJSON is generated by swag from the handler annotations, see the
// "be:docs" task in the Taskfile.
//
//go:embed docs/swagger.json
var swaggerJSON []byte

// docsSwagger godoc
//
//	@Summary		Swagger specification
//	@Description	Returns this Swagger specification.
//	@Tags			Docs
//	@Produce		json
//	@Success		200	{object}	object
//	@Router			/docs/swagger.json [get]
func (t *api) docsSwagger(ctx *gin.Context) {
	ctx.Data(http.StatusOK, "application/json", swaggerJSON)
}
